  1 | import { useRef, useEffect, useState, useCallback } from "react";
  2 | 
  3 | type VisualizerMode = "bars" | "waveform";
  4 | 
  5 | interface AudioVisualizerProps {
  6 |   frequencyData: Uint8Array;
  7 |   waveformData: Uint8Array;
  8 |   isActive: boolean;
  9 |   width?: number;
 10 |   height?: number;
 11 | }
 12 | 
 13 | const DEFAULT_WIDTH = 480;
 14 | const DEFAULT_HEIGHT = 120;
 15 | const BAR_COUNT = 64;
 16 | 
 17 | export function AudioVisualizer({
 18 |   frequencyData,
 19 |   waveformData,
 20 |   isActive,
 21 |   width = DEFAULT_WIDTH,
 22 |   height = DEFAULT_HEIGHT,
 23 | }: AudioVisualizerProps) {
 24 |   const canvasRef = useRef<HTMLCanvasElement>(null);
 25 |   const [mode, setMode] = useState<VisualizerMode>("bars");
 26 |   const animFrameRef = useRef<number | null>(null);
 27 | 
 28 |   const drawBars = useCallback(
 29 |     (ctx: CanvasRenderingContext2D) => {
 30 |       const w = ctx.canvas.width;
 31 |       const h = ctx.canvas.height;
 32 | 
 33 |       ctx.clearRect(0, 0, w, h);
 34 | 
 35 |       if (!isActive) {
 36 |         // Flat line when inactive
 37 |         ctx.strokeStyle = "#00aa55";
 38 |         ctx.lineWidth = 1;
 39 |         ctx.beginPath();
 40 |         ctx.moveTo(0, h / 2);
 41 |         ctx.lineTo(w, h / 2);
 42 |         ctx.stroke();
 43 |         return;
 44 |       }
 45 | 
 46 |       const data = frequencyData;
 47 |       const step = Math.floor(data.length / BAR_COUNT);
 48 |       const barWidth = Math.floor(w / BAR_COUNT) - 1;
 49 |       const gradient = ctx.createLinearGradient(0, h, 0, 0);
 50 |       gradient.addColorStop(0, "#00ff88");
 51 |       gradient.addColorStop(1, "#00ccff");
 52 | 
 53 |       for (let i = 0; i < BAR_COUNT; i++) {
 54 |         // Average a group of frequency bins
 55 |         let sum = 0;
 56 |         for (let j = 0; j < step; j++) {
 57 |           sum += data[i * step + j] || 0;
 58 |         }
 59 |         const avg = sum / step;
 60 |         const barHeight = Math.max(1, (avg / 255) * h);
 61 | 
 62 |         ctx.fillStyle = gradient;
 63 |         ctx.fillRect(i * (barWidth + 1), h - barHeight, barWidth, barHeight);
 64 |       }
 65 |     },
 66 |     [frequencyData, isActive]
 67 |   );
 68 | 
 69 |   const drawWaveform = useCallback(
 70 |     (ctx: CanvasRenderingContext2D) => {
 71 |       const w = ctx.canvas.width;
 72 |       const h = ctx.canvas.height;
 73 | 
 74 |       ctx.clearRect(0, 0, w, h);
 75 | 
 76 |       if (!isActive) {
 77 |         // Flat line when inactive
 78 |         ctx.strokeStyle = "#00aa55";
 79 |         ctx.lineWidth = 1;
 80 |         ctx.beginPath();
 81 |         ctx.moveTo(0, h / 2);
 82 |         ctx.lineTo(w, h / 2);
 83 |         ctx.stroke();
 84 |         return;
 85 |       }
 86 | 
 87 |       const data = waveformData;
 88 |       const step = Math.floor(data.length / w);
 89 | 
 90 |       ctx.strokeStyle = "#00ff88";
 91 |       ctx.lineWidth = 1.5;
 92 |       ctx.beginPath();
 93 | 
 94 |       for (let x = 0; x < w; x++) {
 95 |         const idx = Math.min(x * step, data.length - 1);
 96 |         const val = data[idx] / 128.0; // 0..2 range, center at 1.0
 97 |         const y = (val * h) / 2;
 98 |         if (x === 0) {
 99 |           ctx.moveTo(x, y);
100 |         } else {
101 |           ctx.lineTo(x, y);
102 |         }
103 |       }
104 |       ctx.stroke();
105 |     },
106 |     [waveformData, isActive]
107 |   );
108 | 
109 |   // Animation loop
110 |   useEffect(() => {
111 |     const canvas = canvasRef.current;
112 |     if (!canvas) return;
113 | 
114 |     const ctx = canvas.getContext("2d");
115 |     if (!ctx) return;
116 | 
117 |     let running = true;
118 | 
119 |     const render = () => {
120 |       if (!running) return;
121 |       if (mode === "bars") {
122 |         drawBars(ctx);
123 |       } else {
124 |         drawWaveform(ctx);
125 |       }
126 |       animFrameRef.current = requestAnimationFrame(render);
127 |     };
128 | 
129 |     animFrameRef.current = requestAnimationFrame(render);
130 | 
131 |     return () => {
132 |       running = false;
133 |       if (animFrameRef.current !== null) {
134 |         cancelAnimationFrame(animFrameRef.current);
135 |         animFrameRef.current = null;
136 |       }
137 |     };
138 |   }, [mode, drawBars, drawWaveform]);
139 | 
140 |   const toggleMode = () => {
141 |     setMode((m) => (m === "bars" ? "waveform" : "bars"));
142 |   };
143 | 
144 |   return (
145 |     <div className="audio-visualizer">
146 |       <canvas
147 |         ref={canvasRef}
148 |         width={width}
149 |         height={height}
150 |         className="audio-visualizer-canvas"
151 |       />
152 |       <button
153 |         className="audio-visualizer-toggle"
154 |         onClick={toggleMode}
155 |         title={mode === "bars" ? "Alternar para waveform" : "Alternar para barras"}
156 |       >
157 |         {mode === "bars" ? "〰️" : "📊"}
158 |       </button>
159 |     </div>
160 |   );
161 | }
